// The wire permission belongs to the attempt that produced this response.
// Absence is deliberately false because transport and parse failures can occur
// after an accepted, billable request even when their local status is 502.
export function withReplaySafety(response, safeToReplay = false, retryAfterMs = 0, clientRetrySafe = safeToReplay) {
  const headers = new Headers(response.headers);
  headers.set('x-tokenproxy-replay-safe', String(safeToReplay === true));
  // Stainless-based clients honor this even for 429/5xx. An uncertain attempt
  // must not be regenerated by the client after the gateway refuses replay.
  if (clientRetrySafe !== true) headers.set('x-should-retry', 'false');
  else if (!safeToReplay && !headers.has('x-should-retry')) headers.set('x-should-retry', 'true');
  if (Number.isFinite(retryAfterMs) && retryAfterMs > 0 && !headers.has('retry-after')) headers.set('retry-after', String(Math.max(1, Math.ceil(retryAfterMs / 1000))));
  return new Response(response.body, { status: response.status, statusText: response.statusText, headers });
}
const REJECTED_STATUSES = new Set([400, 401, 402, 403, 404, 405, 413, 415, 422, 429]);

// Use at an actual upstream response boundary. An adapter that turns an
// accepted response or exposed output into an error must carry an explicit
// false permission. A 5xx status alone says nothing about paid acceptance.
export function isReplaySafeRejection(response) {
  if (!response || response.status < 400 || response.status >= 600) return false;
  const permission = response.headers?.get?.('x-tokenproxy-replay-safe');
  if (permission === 'false' || response.headers?.get?.('x-should-retry') === 'false') return false;
  return permission === 'true' || REJECTED_STATUSES.has(response.status);
}

// An account-specific retry prohibition is distinct from accepted generation.
// Only a complete parsed canonical 429 envelope can make that distinction.
export function isSafeQuotaAccountRejection(response, payload) {
  if (response?.status !== 429 || response.headers?.get?.('x-tokenproxy-replay-safe') === 'false') return false;
  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) return false;
  if (Object.keys(payload).some(key => !['error', 'type', 'request_id', 'requestId'].includes(key))) return false;
  if (!payload.error || typeof payload.error !== 'object' || Array.isArray(payload.error)
      || typeof payload.error.message !== 'string' || !payload.error.message.trim()) return false;
  const forbidden = /usage|tokens|cost|output|choices|content|completion|generation|tool|result|accepted/i;
  const pending = [payload];
  let inspected = 0;
  while (pending.length) {
    const value = pending.pop();
    if (++inspected > 1024) return false;
    if (value && typeof value === 'object') {
      for (const [key, child] of Object.entries(value)) {
        if (forbidden.test(key)) return false;
        if (child && typeof child === 'object') pending.push(child);
      }
    }
  }
  return true;
}
